class InvalidAgeError(Exception):
    pass

raw_age = input().strip()
try:
    age = int(raw_age)
    if age < 0 or age > 120:
        raise InvalidAgeError('Age out of range')
except ValueError:
    print('Error: Invalid input')
except InvalidAgeError:
    print('Error: Age out of range')
else:
    print(f'Valid age: {age}')

