practice_challenges.solution_code:
def count_calls(func):
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

@count_calls
def say_hello():
    return 'hello'

n = int(input())
for _ in range(n):
    say_hello()
print(say_hello.calls)

