questions.solution_code:
def retry_on_failure(func):
    def wrapper(*args, **kwargs):
        for attempt in range(3):
            try:
                return func(*args, **kwargs)
            except Exception:
                pass
        return 'Execution Failed'
    return wrapper

fail_count = int(input())
attempts = 0

@retry_on_failure
def test_fn():
    global attempts
    attempts += 1
    if attempts <= fail_count:
        raise RuntimeError('Fail')
    return 'Success'

print(test_fn())

